# ====================
# Structure defaults
# ====================
@configtag rcut Float64 7.0 "Distance beyond which all interactions are neglected." category="structure" see_also=["rcut_tol", "grid_size"]
@configtag rcut_tol Float64 ifelse(get_rcut_pair_selection(conf) == "frame", 0.0, 1.0) "offset (zero point) of the cutoff function w.r.t. `rcut`." category="structure" default_doc="1.0, or 0.0 if rcut_pair_selection = frame" see_also=["rcut", "rcut_pair_selection"]
@configtag rcut_pair_selection String "reference" "positions on which the pair cutoff `rcut` is applied: reference (the reference structure, e.g. the first frame of each system in universal mode or sc_poscar in md mode) or frame (the current, distorted positions, so that the Hamiltonian depends only on the current geometry). With frame, a pair is included iff its distorted distance lies in the support of the cutoff function, i.e. below rcut + rcut_tol for rcut_tol > 0 and below rcut for rcut_tol <= 0 (rcut_tol defaults to 0 in this mode); in pc mode there are no distortions, so the distorted positions are the reference positions)." category="structure" values=["reference", "frame"] see_also=["rcut", "rcut_tol", "grid_size"]
@configtag Rmax Int64 1 "maximum magnitude of translation vectors used for periodic boundaty conditions (default: determined by rcut)." category="structure"
@configtag poscar String "POSCAR" "path to POSCAR file to define base system." category="structure"
@configtag grid_size Float64 get_rcut(conf) "size of the grid cells of the neighbor search; must be at least rcut." category="structure" default_doc="same as rcut"